function aiExpansionDeposit(ai){const t=ai.t,refs=entities.filter(e=>e.type==='refinery'&&e.hp>0);const b=teamBase(t);return deposits.filter(d=>d.left>4000&&!refs.some(r=>dist(r,d)<40)&&!entities.some(e=>hostile({team:t},e)&&e.building&&dist(e,d)<55)).sort((a,c)=>dist(a,b)-dist(c,b))[0]||null}
