function select(list,silent=false){selection=[...new Set(list)].filter(e=>e.hp>0&&e.team===0&&!e.inside);if(selection.length===1){const t=selection[0].type;if(t==='builder')tab='build';else if(PRODUCERS.includes(t))tab='units';else if(t==='radar')tab='upgrades';else if(t==='silo')tab='powers'}updateUI();if(selection.length&&!silent){sfx('select');const u=selection.find(e=>!e.building);if(u)ack(u.type==='builder'?'dozer':'select',!!D(u).vehicle)}}
const PRODUCERS=['hq','barracks','factory','refinery','airfield'];
function selectSameOnScreen(o){const same=entities.filter(e=>e.team===0&&!e.building&&!e.inside&&e.type===o.type&&onScreen(e));if(!same.includes(o))same.push(o);select(same);toast('تم تحديد '+same.length+' × '+D(o).name+' الظاهرين على الشاشة')}
function clickSelect(x,y,add=false,touch=false){const o=entityAt(x,y);const now=performance.now();if(o&&(o.team===0||o.type==='civilian')){if(o.type==='civilian'&&o.team!==0){showInfo(o);return}if(!touch&&!add&&lastClick.id===o.id&&now-lastClick.t<420&&!o.building){selectSameOnScreen(o)}else select(add?(selection.includes(o)?selection.filter(e=>e!==o):[...selection,o]):[o]);if(!IS_TOUCH)lastClick={t:now,id:o.id}}else if(o&&o.team===1){showInfo(o)}else if(!add)select([])}
function onScreen(e){const p=project(e,-1);return p.visible&&p.x>0&&p.x<innerWidth&&p.y>48&&p.y<hudTop}
let inspect=null;function showInfo(o){inspect=o;select([],true);updateUI()}

