function cancelMode(){placement=null;targeting=null;pending=null;$('placeBar').hidden=true;boxMode=false;$('tBox')?.classList.remove('on');if(ghost){scene.remove(ghost.root);scene.remove(ghost.foot);ghost=null}$('orderHint').hidden=true}
function chooseBuild(type){if(type==='silo'&&!settings.superweapons)return;const miss=missingRequirement(type,0);if(miss){toast('يتطلب '+D(miss,0).name,true);sfx('error');return}if(teams[0].money<costOf(type,0)){toast('رصيد غير كافٍ',true);sfx('error');say('money',6000);return}if(!idleBuilder(0,teamBase(0))){toast('لا توجد شاحنة بناء متاحة — أنتج واحدة من مركز القيادة',true);sfx('error');return}if(D(type,0).limit&&count(type,0)>=D(type,0).limit){toast('مسموح بمنصة واحدة فقط',true);return}{const ps=powerShort(type,0);if(ps>0){toast('طاقة غير كافية: '+D(type,0).name+' يحتاج '+ps+' طاقة إضافية — ابنِ '+D('power',0).name,true);sfx('error');say('lowpower',5000);return}}
 cancelMode();placement=type;if(IS_TOUCH)autoSpot(type);const root=makeAsset(type,0,{faction:teams[0].faction});root.userData.opacity=.55;root.userData.noShadow=true;scene.add(root);const foot=new T.Object3D();foot.userData={layer:'ground',draw(ctx,H,ob,p){const r=D(type,0).r+.5,ok=ghost?.ok,ox=ob.position.x,oz=ob.position.z,y=ob.position.y;ctx.save();ctx.strokeStyle='#ffffff22';ctx.lineWidth=1;const G=r+6;for(let k=-G;k<=G;k+=2){const a1=H.project(ox+k,y,oz-G),a2=H.project(ox+k,y,oz+G),b1=H.project(ox-G,y,oz+k),b2=H.project(ox+G,y,oz+k);ctx.beginPath();ctx.moveTo(a1.x,a1.y);ctx.lineTo(a2.x,a2.y);ctx.moveTo(b1.x,b1.y);ctx.lineTo(b2.x,b2.y);ctx.stroke()}const c=[[-r,-r],[r,-r],[r,r],[-r,r]].map(([dx,dz])=>H.project(ox+dx,y,oz+dz));ctx.fillStyle=ok?'#7fe0a040':'#ff5a4040';ctx.strokeStyle=ok?'#9ff0b8':'#ff7a5a';ctx.lineWidth=2;ctx.beginPath();c.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.closePath();ctx.fill();ctx.stroke();if(!ok&&ghost?.reason&&!IS_TOUCH){ctx.font='bold 12px Tahoma';ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#000c';ctx.strokeText('✕ '+ghost.reason,p.x,c[2].y+18);ctx.fillStyle='#ff9a80';ctx.fillText('✕ '+ghost.reason,p.x,c[2].y+18)}ctx.restore()}};scene.add(foot);ghost={root,foot,ok:false};$('orderHint').hidden=false;$('orderHint').textContent='اختر موقع '+D(type,0).name+' · الشاحنة ستنتقل إلى الموقع'+(IS_TOUCH?' · المس هنا للإلغاء':' · زر يمين أو Esc للإلغاء')}
function autoSpot(type){const c=snap(centerGround());if(!placeReason(type,c))return;for(let i=1;i<400;i++){const a=i*2.39996,r=Math.sqrt(i)*2.2,q=snap({x:c.x+Math.cos(a)*r,z:c.z+Math.sin(a)*r});if(!placeReason(type,q)){cam.x=clamp(cam.x+q.x-c.x,-MAP.cameraLimit,MAP.cameraLimit);cam.z=clamp(cam.z+q.z-c.z,-MAP.cameraLimit,MAP.cameraLimit);return}}}
function placeAt(x,y){placeAtWorld(snap(groundAt(x,y)))}
function placeAtWorld(p){const why=placeReason(placement,p);if(why){toast('لا يمكن البناء هنا: '+why,true);sfx('error');say('cantbuild',4000);return}const site=requestConstruction(placement,0,p);if(!site){toast('لا توجد شاحنة بناء متاحة أو مسار صالح',true);sfx('error');return}toast('شاحنة البناء في طريقها لإنشاء '+D(site).name);sfx('click');ack('dozerGo');const keep=keys.has('ShiftLeft')||keys.has('ShiftRight');const type=placement;cancelMode();if(keep&&canBuy(type))chooseBuild(type);updateUI()}
function canBuy(type){return!!teams[0]&&teams[0].money>=costOf(type,0)&&!missingRequirement(type,0)}
function buyUnit(type){const miss=missingRequirement(type,0);if(miss){toast('يتطلب '+D(miss,0).name,true);sfx('error');return}if(teams[0].money<costOf(type,0)){toast('رصيد غير كافٍ',true);sfx('error');say('money',6000);return}if(committedPop(0)>=POP_CAP){toast('بلغت الحد الأقصى للقوات ('+POP_CAP+')',true);return}const pr=prodSel();let pref=null;if(pr){const same=selection.filter(e=>e.type===pr.type&&madeAt(type,0).includes(e.type)&&e.queue.length<9);pref=same.sort((a,c)=>a.queue.length-c.queue.length)[0]||null}if(enqueueUnit(type,0,pref)){sfx('click');updateUI()}else{toast('قائمة الإنتاج ممتلئة',true);sfx('error')}}
function startTargeting(kind,id){const keepSel=selection.slice();cancelMode();targeting={kind,id,keepSel};$('orderHint').hidden=false;$('orderHint').textContent=(kind==='rally'?'حدد مكان تجمّع الوحدات الجديدة':kind==='silo'?'حدد هدف الصاروخ الاستراتيجي':'حدد موقع: '+POWERS[id].name)+(IS_TOUCH?' · المس هنا للإلغاء':' · زر يمين أو Esc للإلغاء');const r=kind==='rally'?2:kind==='silo'?(FA(0).sw.kind==='nuke'?38:24):POWERS[id].radius||6;const foot=new T.Object3D();foot.userData={layer:'ground',draw(ctx,H,ob,p){const s=H.scaleAt(ob.position.x,0,ob.position.z),rr=r*s;ctx.save();ctx.strokeStyle=kind==='silo'?'#ff5a40':'#ffd27a';ctx.setLineDash([6,5]);ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x,p.y,rr,rr*H.squash,0,0,7);ctx.stroke();ctx.restore()}};scene.add(foot);ghost={root:new T.Object3D(),foot,ok:true}}
function executeTarget(x,y){executeTargetWorld(groundAt(x,y))}
function executeTargetWorld(p){if(targeting.kind==='rally'){const bs=targeting.keepSel.filter(b=>b.hp>0&&PRODUCERS.includes(b.type));bs.forEach(b=>b.rally={x:p.x,z:p.z});marker(p.x,p.z,0xe9c46a,2);toast('تم تعيين نقطة التجمّع: الوحدات الجديدة ستتجه إليها');sfx('click');cancelMode();updateUI();return}if(targeting.kind==='silo'){const s=live(0,'silo').find(s=>s.charge<=0);if(s)launchSilo(s,p)}else usePower(0,targeting.id,p);cancelMode();updateUI()}
function clickPower(id){const P=POWERS[id],st=teams[0].powers[id];if(!st.unlocked){openPromo();return}if(!exists(P.needs,0)){toast('يتطلب '+D(P.needs,0).name,true);sfx('error');return}if(st.cd>0){toast(P.name+' غير جاهزة بعد',true);sfx('error');return}if(P.instant){usePower(0,id,teamBase(0));updateUI();return}startTargeting('power',id)}

