function toast(msg,danger=false,kind=''){const el=document.createElement('div');el.className='toast'+(danger?' danger':'')+(kind?' '+kind:'');el.textContent=msg;$('alerts').append(el);setTimeout(()=>el.remove(),5000);while($('alerts').children.length>5)$('alerts').firstChild.remove()}
const fmt=n=>'$ '+Math.floor(n).toLocaleString('en-US'),mmss=s=>Math.floor(s/60).toString().padStart(2,'0')+':'+Math.floor(s%60).toString().padStart(2,'0');
