let lastCards='',lastQueue='',lastSel='';
function prodSel(){const s=selection;return s.length&&s.every(e=>e.building&&e.team===0&&e.progress>=1&&PRODUCERS.includes(e.type)&&e.type===s[0].type)?s[0]:null}
function cardAction(t){if(tab==='build')chooseBuild(t);else if(tab==='units')buyUnit(t);else if(tab==='upgrades'){if(research(t,0)){sfx('click');toast('بدأ البحث: '+UPGRADES[t].name);updateUI()}}else if(t==='silo-fire')startTargeting('silo');else clickPower(t)}
function onTap(el,sel,fn){let d=null;el.addEventListener('pointerdown',ev=>{if(ev.pointerType==='mouse'&&ev.button!==0)return;const b=ev.target.closest(sel);d=b?{b,x:ev.clientX,y:ev.clientY}:null});el.addEventListener('pointerup',ev=>{const t=d;d=null;if(!t||Math.hypot(ev.clientX-t.x,ev.clientY-t.y)>12)return;fn(t.b)});el.addEventListener('pointercancel',()=>d=null)}
