function drawMinimap(){const c=$('minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height,L=MAP.limit,px=x=>(x+L)/(L*2)*w,pz=z=>(z+L)/(L*2)*h;ctx.fillStyle=BIOMES[MAP.biome].mini;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#52604744';ctx.lineWidth=1;for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(i*w/8,0);ctx.lineTo(i*w/8,h);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*h/8);ctx.lineTo(w,i*h/8);ctx.stroke()}
 ctx.strokeStyle='#b1ac7848';ctx.lineWidth=3;for(const road of MAP.roads){ctx.beginPath();road.forEach(([x,z],i)=>i?ctx.lineTo(px(x),pz(z)):ctx.moveTo(px(x),pz(z)));ctx.stroke()}
 for(const o of mapObstacles(MAP)){ctx.fillStyle=o.kind==='grove'?BIOMES[MAP.biome].grove:BIOMES[MAP.biome].obstacle;ctx.beginPath();ctx.arc(px(o.x),pz(o.z),Math.max(2,o.r/L/2*w*1.3),0,7);ctx.fill()}
 for(const d of deposits){ctx.fillStyle=d.left>0?'#d4bb72':'#5e6250';ctx.fillRect(px(d.x)-3,pz(d.z)-3,6,6)}
 for(const e of entities){if(e.inside)continue;ctx.fillStyle=selection.includes(e)?'#fff1c6':TEAM[e.team].color;const r=e.type==='hq'?4:e.building?2.8:1.5;ctx.fillRect(px(e.x)-r,pz(e.z)-r,r*2,r*2)}
 for(const p of pings){p.t+=1/15;const r=(p.big?10:5)+((p.t*20)%12);ctx.strokeStyle=p.color;ctx.globalAlpha=Math.max(0,1-p.t/4);ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(px(p.x),pz(p.z),r,0,7);ctx.stroke();ctx.globalAlpha=1}pings=pings.filter(p=>p.t<4);
 const top=document.querySelector('header').offsetHeight||68,corners=[[0,top],[innerWidth,top],[innerWidth,hudTop],[0,hudTop]].map(([x,y])=>groundAt(x,y));ctx.strokeStyle='#e7e0c1cc';ctx.lineWidth=1;ctx.beginPath();corners.forEach((p,i)=>i?ctx.lineTo(px(p.x),pz(p.z)):ctx.moveTo(px(p.x),pz(p.z)));ctx.closePath();ctx.stroke()}

