const rallyDraw=new T.Object3D();rallyDraw.userData={layer:'ground',draw(ctx,H){if(!running)return;const list=entities.filter(b=>b.team===0&&b.rally&&b.hp>0&&(selection.includes(b)||targeting?.kind==='rally'&&targeting.keepSel.includes(b)));for(const b of list){const a=H.project(b.x,height(b.x,b.z),b.z),r=H.project(b.rally.x,height(b.rally.x,b.rally.z),b.rally.z);if(a.z>1||r.z>1)continue;const s=H.scaleAt(b.rally.x,0,b.rally.z),t=H.time;ctx.save();ctx.setLineDash([7,6]);ctx.lineDashOffset=-t*20;ctx.strokeStyle='#f3d27acc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(r.x,r.y);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#f3d27a';ctx.beginPath();ctx.ellipse(r.x,r.y,s*1.6,s*1.6*H.squash,0,0,7);ctx.stroke();const ph=s*4.2;ctx.strokeStyle='#2a261e';ctx.lineWidth=Math.max(2,s*.18);ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x,r.y-ph);ctx.stroke();ctx.fillStyle='#7fc4e8';ctx.beginPath();ctx.moveTo(r.x,r.y-ph);for(let i=0;i<=8;i++){const u=i/8;ctx.lineTo(r.x+u*s*2.6,r.y-ph+Math.sin(t*5+u*4)*s*.25*u)}for(let i=8;i>=0;i--){const u=i/8;ctx.lineTo(r.x+u*s*2.6,r.y-ph+s*1.4+Math.sin(t*5+u*4)*s*.25*u-u*s*.2)}ctx.closePath();ctx.fill();ctx.restore()}}};scene.add(rallyDraw);
function hudFrame(){rallyDraw.position.set(cam.x,0,cam.z);const groupOf=new Map();for(const g in groups)for(const e of groups[g])groupOf.set(e,g);for(const e of entities){const u=e.root.userData,sel=selection.includes(e),hover=e===hoverEntity||e===inspect;u.tc=!e.building&&isPlayer(e.team)&&!e.inside?TEAM[e.team].color:null;u.ring=sel?'#f2f6d8':(!e.building&&isPlayer(e.team)?TEAM[e.team].ring:hover&&e.building?TEAM[e.team].ring:null);const show=sel||hover||timer-e.lastHit<4||e.progress<1||(e.building&&e.hp<e.maxhp*.5)||keys.has('AltLeft');const showHud=show||e.vet||groupOf.has(e)||(e.type==='civilian'&&e.garrison.length)||(e.type==='silo');
  u.hud=showHud&&running?{building:e.building,hp:e.hp/e.maxhp,showHp:show,progress:e.progress<1?e.progress:undefined,vet:e.vet,group:groupOf.get(e),team:e.team,pips:e.type==='civilian'?[e.garrison.length,defs.civilian.capacity]:null,text:e.off>timer?'⚠ معطّل':e.type==='silo'&&e.progress>=1?(e.charge>0?mmss(e.charge):'جاهز!'):null}:null}}

