let enemyCycle=0;$('enemyBtn').onclick=()=>{const list=teams.map((tm,t)=>t).filter(t=>!teams[t].dead&&hostile({team:0},{team:t}));if(!list.length)return;const t=list[enemyCycle++%list.length],b=teamBase(t);cam.x=b.x;cam.z=b.z;toast('قاعدة '+TEAM[t].name)};$('homeBtn').onclick=()=>{const b=teamBase(0);cam.x=b.x;cam.z=b.z};$('armyBtn').onclick=()=>select(entities.filter(e=>e.team===0&&!e.building&&!e.inside&&D(e).weapon));$('stopBtn').onclick=()=>stopUnits(selection);
