$('mapSel').onchange=()=>{const m=MAPS.find(m=>m.id===$('mapSel').value);$('mapDesc').textContent=m.desc;if(lobby.length>m.max){lobby=lobby.slice(0,m.max);toast('هذه الخريطة تتسع لـ'+m.max+' لاعبين فقط')}renderLobby();preview(m.id)};
const PRESETS=[['1 ضد 1',[1,2]],['2 ضد 2',[1,1,2,2]],['أنا ضد 2',[1,2,2]],['أنا ضد 4',[1,2,2,2,2]],['4 ضد 1',[1,1,1,1,2]],['3 ضد 3',[1,1,1,2,2,2]],['الكل ضد الكل',[11,12,13,14]]];
function curMap(){return MAPS.find(m=>m.id===$('mapSel').value)||MAPS[0]}
function renderLobby(){const m=curMap(),fo=k=>FACTION_KEYS.map(f=>`<option value="${f}" ${k===f?'selected':''}>${FACTIONS[f].name}</option>`).join('');let ai=0;
 $('slots').innerHTML=lobby.map((sl,i)=>{const c=TEAM[i].color,teamOpts=[1,2,3,4].map(n=>`<option value="${n}" ${sl.team===n?'selected':''}>فريق ${n}</option>`).join('')+`<option value="${10+i}" ${sl.team>=10?'selected':''}>بدون فريق</option>`;
  return`<div class="slot ${i?'':'me'}" data-i="${i}" style="--pc:${c}"><i class="pc" title="${PCOL[i][1]}"></i><b>${i?'كمبيوتر '+(++ai):'أنت'}</b>${i?`<select data-k="faction" aria-label="الجيش"><option value="random" ${sl.faction==='random'?'selected':''}>جيش عشوائي</option>${fo(sl.faction)}</select><select data-k="diff" aria-label="القوة"><option value="easy" ${sl.diff==='easy'?'selected':''}>سهل</option><option value="normal" ${sl.diff==='normal'?'selected':''}>متوسط</option><option value="hard" ${sl.diff==='hard'?'selected':''}>صعب</option></select>`:`<span class="me-f">${sl.faction==='random'?'جيش عشوائي':FACTIONS[sl.faction].name}</span><span class="me-d">القائد</span>`}<select data-k="team" aria-label="الفريق">${teamOpts}</select>${i?'<button data-rm title="إزالة">✕</button>':'<span></span>'}</div>`}).join('');
 $('addAI').disabled=lobby.length>=m.max;$('addAI').textContent=lobby.length>=m.max?'الخريطة ممتلئة ('+m.max+' لاعبين)':'+ أضف كمبيوتر';
 const al=new Set(lobby.map(s=>s.team)),mine=lobby.filter(s=>s.team===lobby[0].team).length;$('lobbySum').textContent=al.size<2?'⚠ الكل في فريق واحد — اجعل خصماً واحداً على الأقل في فريق آخر':(mine>1?'أنت و'+(mine-1)+' حليف':'أنت وحدك')+' ضد '+(lobby.length-mine)+' · '+m.name;$('lobbySum').classList.toggle('bad',al.size<2);$('start').disabled=al.size<2}
$('presets').innerHTML=PRESETS.map(([n],i)=>`<button data-p="${i}">${n}</button>`).join('');
onTap($('presets'),'button',b=>{const tms=PRESETS[+b.dataset.p][1];let m=curMap();if(tms.length>m.max){m=MAPS.find(x=>x.max>=tms.length&&x.biome===m.biome)||MAPS.find(x=>x.max>=tms.length);$('mapSel').value=m.id;$('mapDesc').textContent=m.desc;preview(m.id);toast('اخترت خريطة '+m.name+' لأنها تتسع لـ'+tms.length+' لاعبين')}lobby=tms.map((tm,i)=>i?{ai:true,faction:lobby[i]?.faction||'random',diff:lobby[i]?.diff||'normal',team:tm}:{...lobby[0],team:tm});renderLobby();sfx('click')});
$('slots').addEventListener('change',e=>{const row=e.target.closest('.slot'),k=e.target.dataset.k;if(!row||!k)return;const sl=lobby[+row.dataset.i];sl[k]=k==='team'?+e.target.value:e.target.value;renderLobby()});
onTap($('slots'),'button[data-rm]',b=>{const i=+b.closest('.slot').dataset.i;lobby.splice(i,1);renderLobby();sfx('click')});
$('addAI').onclick=()=>{if(lobby.length>=curMap().max)return;lobby.push({ai:true,faction:'random',diff:'normal',team:2});renderLobby();sfx('click')};$('factionSel').onchange=()=>$('facDesc').textContent=$('factionSel').value==='random'?'فصيل عشوائي':FACTIONS[$('factionSel').value].desc;
function panCameraByPixels(dx,dy){const scale=2*cam.zoom*Math.tan(camera.fov*Math.PI/360)/innerHeight,wx=-dx*scale,wz=-dy*scale/.8;cam.x=clamp(cam.x+wx*Math.cos(cam.angle)+wz*Math.sin(cam.angle),-MAP.cameraLimit,MAP.cameraLimit);cam.z=clamp(cam.z+wz*Math.cos(cam.angle)-wx*Math.sin(cam.angle),-MAP.cameraLimit,MAP.cameraLimit)}
const canvas=renderer.domElement;canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(!running||paused||ended)return;pointer.x=e.clientX;pointer.y=e.clientY;$('promo').hidden=true;if(e.button===2||e.button===1){e.preventDefault();if(e.button===2&&(placement||targeting)){cancelMode();return}rdrag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,active:false,shift:e.shiftKey,order:e.button===2};canvas.setPointerCapture(e.pointerId);return}if(e.button!==0)return;if(placement&&e.pointerType!=='touch'){placeAt(e.clientX,e.clientY);return}if(targeting&&e.pointerType!=='touch'){executeTarget(e.clientX,e.clientY);return}if(e.shiftKey||boxMode||e.pointerType==='mouse'){drag={x:e.clientX,y:e.clientY,shift:e.shiftKey||boxMode&&e.pointerType!=='mouse'};dragging=false}else cameraDrag={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,active:false,t:performance.now()};canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY;if(!running||paused)return;if(rdrag){if(Math.hypot(e.clientX-rdrag.x,e.clientY-rdrag.y)>6)rdrag.active=true;if(rdrag.active)panCameraByPixels(e.clientX-rdrag.lastX,e.clientY-rdrag.lastY);rdrag.lastX=e.clientX;rdrag.lastY=e.clientY;return}if(cameraDrag){const d=cameraDrag;if(Math.hypot(e.clientX-d.x,e.clientY-d.y)>(e.pointerType==='touch'?14:6))d.active=true;if(d.active)panCameraByPixels(e.clientX-d.lastX,e.clientY-d.lastY);d.lastX=e.clientX;d.lastY=e.clientY;return}if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>7){dragging=true;const b=$('selectionBox');b.style.display='block';Object.assign(b.style,{left:Math.min(drag.x,e.clientX)+'px',top:Math.min(drag.y,e.clientY)+'px',width:Math.abs(dx)+'px',height:Math.abs(dy)+'px'})}}});
canvas.addEventListener('pointerup',e=>{if(rdrag&&(e.button===2||e.button===1)){const r=rdrag;rdrag=null;canvas.releasePointerCapture?.(e.pointerId);if(!r.active&&r.order&&running&&!paused&&!ended)giveOrder(e.clientX,e.clientY,r.shift||e.shiftKey);return}if(e.button!==0)return;if(cameraDrag){const g=cameraDrag;cameraDrag=null;if(running&&!paused&&!ended&&!g.active&&Math.hypot(e.clientX-g.x,e.clientY-g.y)<=(e.pointerType==='touch'?14:6)){if(e.pointerType==='touch'&&performance.now()-g.t>550){if(!entityAt(e.clientX,e.clientY,16)){select([]);toast('أُلغي التحديد')}}else(e.pointerType==='touch'?touchTap:clickSelect)(e.clientX,e.clientY)}canvas.releasePointerCapture?.(e.pointerId);return}if(!drag)return;if(running&&!paused){if(dragging){const x0=Math.min(drag.x,e.clientX),x1=Math.max(drag.x,e.clientX),y0=Math.min(drag.y,e.clientY),y1=Math.max(drag.y,e.clientY);const list=entities.filter(o=>{const p=project(o,-1);return o.team===0&&!o.building&&!o.inside&&p.visible&&p.x>=x0&&p.x<=x1&&p.y>=y0&&p.y<=y1});select(drag.shift?[...selection,...list]:list);if(list.length&&!drag.shift&&e.pointerType==='mouse')toast('تم تحديد '+list.length+' وحدة')}else clickSelect(e.clientX,e.clientY,drag.shift)}if(boxMode&&dragging){boxMode=false;$('tBox')?.classList.remove('on')}drag=null;dragging=false;$('selectionBox').style.display='none';canvas.releasePointerCapture?.(e.pointerId)});
const endDrag=()=>{cameraDrag=null;rdrag=null;drag=null;dragging=false;$('selectionBox').style.display='none'};canvas.addEventListener('pointercancel',endDrag);canvas.addEventListener('lostpointercapture',endDrag);
