function centerGround(){const head=document.querySelector('header')?.offsetHeight||0;return groundAt(innerWidth/2,(head+hudTop)/2)}
function updatePlaceBar(){const bar=$('placeBar');bar.hidden=false;if(placement){const ok=ghost?.ok;$('placeMsg').textContent=ok?'اسحب الخريطة لتحريك '+D(placement,0).name+' ثم أكّد':'✕ '+(ghost?.reason||'');$('placeMsg').className=ok?'':'bad';$('placeOk').disabled=!ok;$('placeOk').textContent='✓ ابنِ هنا'}else if(targeting){$('placeMsg').textContent='اسحب الخريطة لتوجيه الهدف ثم أكّد';$('placeMsg').className='';$('placeOk').disabled=false;$('placeOk').textContent=targeting.kind==='rally'?'✓ ثبّت التجمّع':'✓ تنفيذ'}}
function touchTap(x,y){const p=groundAt(x,y);
 if(placement||targeting&&targeting.kind!=='rally'){const c=centerGround();cam.x=clamp(cam.x+p.x-c.x,-MAP.cameraLimit,MAP.cameraLimit);cam.z=clamp(cam.z+p.z-c.z,-MAP.cameraLimit,MAP.cameraLimit);sfx('click');return}
 if(targeting&&targeting.kind==='rally'){executeTargetWorld(p);return}
 if(false&&targeting){const r=targeting.kind==='silo'?24:POWERS[targeting.id].radius||6;if(pending&&Math.hypot(p.x-pending.x,p.z-pending.z)<Math.max(6,r*.6)){const w=pending;pending=null;executeTargetWorld(w)}else{pending=p;$('orderHint').textContent='المس داخل الدائرة مرة أخرى للتأكيد · المس هنا للإلغاء';sfx('click')}return}
 const o=entityAt(x,y,16),units=selection.filter(e=>!e.building),now=performance.now();
 if(o&&o.team===0&&!o.building&&lastClick.id===o.id&&now-lastClick.t<420){lastClick={t:0,id:null};selectSameOnScreen(o);return}
 if(o&&o.team===0&&selection.length===1&&selection[0]===o){lastClick={t:now,id:o.id};select([]);return}
 if(o&&o.team===0)lastClick={t:now,id:o.id};
 // a production building is selected and the player taps open ground: set its rally point
 if(!units.length&&selection.some(e=>PRODUCERS.includes(e.type))&&(!o||o.team!==0)){giveOrder(x,y);return}
 if(o&&o.team===0){const needsWork=o.building&&(o.progress<1||o.hp<o.maxhp*.98)&&units.some(e=>e.type==='builder'),dock=o.type==='refinery'&&units.some(e=>e.type==='harvester');if((needsWork||dock)&&!selection.includes(o)){giveOrder(x,y);return}clickSelect(x,y,false,true);return}
 if(units.length){if(!touchHintShown){touchHintShown=true;toast('المس أي مكان لإرسال الوحدات · لمستان على جندي = كل الجنود · ✕ لإلغاء التحديد')}giveOrder(x,y);if(attackToggle){attackToggle=false;$('tAttack').classList.remove('on')}return}clickSelect(x,y)}
const touches=new Map();let pinch=null,touchHintShown=false;
canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size===2){const[a,b]=[...touches.values()];pinch={d:Math.hypot(a.x-b.x,a.y-b.y)||1,zoom:cam.zoom,cx:(a.x+b.x)/2,cy:(a.y+b.y)/2};cameraDrag=null;drag=null;dragging=false;$('selectionBox').style.display='none'}});
canvas.addEventListener('pointermove',e=>{if(!touches.has(e.pointerId))return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pinch&&touches.size>=2){const[a,b]=[...touches.values()];cam.zoom=clamp(pinch.zoom*pinch.d/(Math.hypot(a.x-b.x,a.y-b.y)||1),34,190);const cx=(a.x+b.x)/2,cy=(a.y+b.y)/2;panCameraByPixels(cx-pinch.cx,cy-pinch.cy);pinch.cx=cx;pinch.cy=cy}});
const touchEnd=e=>{touches.delete(e.pointerId);if(touches.size<2)pinch=null};canvas.addEventListener('pointerup',touchEnd);canvas.addEventListener('pointercancel',touchEnd);
