function measureHud(){const f=document.querySelector('footer');hudTop=f&&f.offsetParent?f.getBoundingClientRect().top:innerHeight-240;const head=document.querySelector('header')?.offsetHeight||0;
 // centre the camera focus in the visible play area (between the top bar and the bottom panel)
 const off=running?Math.round(((innerHeight-hudTop)-head)/2):0;if(off>0)camera.setViewOffset(innerWidth,innerHeight,0,off,innerWidth,innerHeight);else camera.clearViewOffset();camera.updateProjectionMatrix();renderer.groundKey='';document.documentElement.style.setProperty('--hudh',Math.max(0,innerHeight-hudTop)+'px')}addEventListener('resize',()=>setTimeout(measureHud,50));
